#include "stdafx.h"#include "StateSer.h"#include <rsuErr.h>enum EStateKeys{  eKeyMagicDW = 0x5A8E845E,};KStateSer::KStateSer( LPCSTR pszFile, bool bSave ): m_hFile( INVALID_HANDLE_VALUE ), m_dwFileSize( 0 ), m_dwCurr( 0 ), m_bStartCalled( false ), m_bCompleteCalled( false ), m_dwStartPos( 0 ), m_saverVerFormat( 0 ){  bool res = bSave ? Create(pszFile) : Open(pszFile);  ASS( res );  m_bRead = !bSave;}KStateSer::KStateSer( HANDLE hFile, bool bSave ): m_hFile( hFile ), m_dwFileSize( 0 ), m_dwCurr( 0 ), m_dwStartPos( 0 ){  m_bRead = !bSave;  DWORD H = 0;  m_dwFileSize = GetFileSize( m_hFile, &H );  ASS( !H );}KStateSer::~KStateSer(){  if( !m_bRead )  {    ASS( m_bStartCalled );    ASS( m_bCompleteCalled );  }  Close();}bool KStateSer::Close(){  if( INVALID_HANDLE_VALUE==m_hFile )    return false;  BOOL r = CloseHandle( m_hFile );  ASS( r );  m_hFile = INVALID_HANDLE_VALUE;  return true;}void KStateSer::OnWrote( DWORD size ){  m_dwCurr += size;  m_dwFileSize += size;}void KStateSer::OnRead( DWORD size ){  m_dwCurr += size;}bool KStateSer::Create( LPCSTR pszFile ){  m_hFile = CreateFile( pszFile,                        GENERIC_WRITE,                        FILE_SHARE_READ|FILE_SHARE_WRITE,                        NULL,                        CREATE_ALWAYS,                        FILE_FLAG_SEQUENTIAL_SCAN,                        NULL );  return INVALID_HANDLE_VALUE != m_hFile;}bool KStateSer::Open( LPCSTR pszFile ){  DWORD dwFlagsAndAttributes = FILE_FLAG_SEQUENTIAL_SCAN;  m_hFile = CreateFile( pszFile,                        GENERIC_READ,                        FILE_SHARE_READ|FILE_SHARE_WRITE,                        NULL,                        OPEN_EXISTING,                        dwFlagsAndAttributes,                        NULL );  if( INVALID_HANDLE_VALUE == m_hFile )    return false;  DWORD H = 0;  m_dwFileSize = GetFileSize( m_hFile, &H );  ASS( !H );  return true;}void KStateSer::StartSave(){  m_bStartCalled = true;  Write( eKeyMagicDW );  m_dwStartPos = GetPosition();  Write( m_dwStartPos );}void KStateSer::SaveCompleted(){  m_bCompleteCalled = true;  DWORD &curPos = m_dwCurr;  DWORD r = SetFilePointer( m_hFile, m_dwStartPos, NULL, FILE_BEGIN );  DWORD length = curPos - m_dwStartPos;  m_dwCurr -= 4;  Write( length );  r = SetFilePointer( m_hFile, 0, NULL, FILE_END );  ASS( m_dwCurr==r );  m_dwCurr = r;}int KStateSer::StartRestore(){  bool r = CompareOnRead( eKeyMagicDW );  ASS( r );  int legth = 0;  Read( legth );  return legth;}DWORD KStateSer::WriteImpl( const void *pObj, DWORD objSize ){  DWORD start = GetPosition();  DWORD Lw = 0;  ::WriteFile ( m_hFile, pObj, objSize, &Lw, NULL );  ASSD( objSize==Lw );  OnWrote( Lw );  DWORD end = GetPosition();  return end - start;}DWORD KStateSer::ReadImpl( void *pObj, DWORD objSize ){  DWORD Lr = 0;  if( !::ReadFile( m_hFile, pObj, objSize, &Lr, NULL ) )  {    return 0;  }  ASSD( Lr==objSize );  OnRead( objSize );  return Lr;}DWORD KStateSer::RawRead( void *pOut, DWORD objSize ){  return ReadImpl( pOut, objSize );}DWORD KStateSer::GetPosition(){  return m_dwCurr;}DWORD KStateSer::WriteAtPositionImpl( DWORD shiftFromBegin, const void *pObj, DWORD objSize ){  DWORD &curPos = m_dwCurr;  DWORD r = SetFilePointer( m_hFile, shiftFromBegin, NULL, FILE_BEGIN );  curPos = shiftFromBegin;  DWORD l = WriteImpl( pObj, objSize );  r = SetFilePointer( m_hFile, 0, NULL, FILE_END );  m_dwCurr = r;  return l;}void KStateSer::Skip( DWORD shift ){  m_dwCurr = SetFilePointer( m_hFile, shift, NULL, FILE_CURRENT );}void KStateSer::WriteDotV( SDotValue *pV, LPCSTR pszName ){  Write( pszName );  DWORD s = pV ? sizeof(*pV) : 0;  Write( s );  if( !pV )    return ;  Write( *pV );}int KStateSer::ReadDotV( SDotValue *pV, LPCSTR pszName ){  char szName[32];  Read( szName );  if( strcmp(szName, pszName) )  {    ASSD( 0 );    return -1;  }  DWORD s = 0;  Read( s );  if( !pV )  {    if( !s )      return 0;    Skip( s );    return 0;  }  if( s!=sizeof(*pV) )    Skip( s );  else    Read( *pV );  return 0;}void KStateSer::SetSavedVersionFormat( DWORD v ){  m_saverVerFormat = v;}DWORD KStateSer::GetSavedVersionFormat(){  return m_saverVerFormat;}